/**
 * mockApi — fake async helpers for prototypes.
 *
 * Use these to demo loading + error states with the design system's
 * loading / invalid props (Button.loading, Alert variant="danger", etc).
 */

export function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

export type MockOpts = {
  delayMs?: number
  /** Probability between 0 and 1 of a synthetic failure. */
  failRate?: number
  /** Error message used when the fake call rejects. */
  errorMessage?: string
}

export async function mockSubmit<T>(payload: T, opts: MockOpts = {}): Promise<T> {
  const { delayMs = 800, failRate = 0, errorMessage = "Something went wrong. Please try again." } = opts
  await delay(delayMs)
  if (failRate > 0 && Math.random() < failRate) {
    throw new Error(errorMessage)
  }
  return payload
}

/** Returns true after a random delay, simulating an OTP verification. */
export async function mockVerifyOtp(code: string, opts: MockOpts = {}): Promise<boolean> {
  const { delayMs = 700 } = opts
  await delay(delayMs)
  // Demo rule: "0000" always fails, anything else passes.
  if (code === "0000") {
    throw new Error("That code didn't match. Try again.")
  }
  return true
}

"use client"

import React from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { TabbyStepProps } from "../schema"

/**
 * Success — simplified "stores" home that lands after onboarding.
 * Mirrors the last screen of the source flow at a high level only.
 */
export function Success({ goTo }: TabbyStepProps) {
  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", overflowY: "auto" }}>
      {/* Header search */}
      <div style={{ padding: "var(--atlas-spacing-4) var(--atlas-spacing-5)" }}>
        <Input
          placeholder="Stores or products"
          leadingIcon={<span aria-hidden style={{ fontSize: 14 }}>🔍</span>}
          size="md"
        />
      </div>

      {/* Quick links */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "var(--atlas-spacing-3)",
          padding: "0 var(--atlas-spacing-5)",
        }}
      >
        <QuickLink emoji="🛒" title="All stores" sub="Shop and split" />
        <QuickLink emoji="🏷️" title="Deals" sub="Discounts up to 30%" />
      </div>

      {/* Categories row */}
      <div
        style={{
          display: "flex",
          gap: "var(--atlas-spacing-3)",
          padding: "var(--atlas-spacing-5)",
          overflowX: "auto",
        }}
      >
        {[
          { emoji: "💸", label: "Customise your Tabby" },
          { emoji: "📱", label: "Mobile" },
          { emoji: "💍", label: "Jewelry" },
        ].map((c) => (
          <div key={c.label} style={{ minWidth: 110 }}>
            <Card variant="outlined" size="sm">
              <CardContent>
                <div style={{ fontSize: 24 }}>{c.emoji}</div>
                <div
                  style={{
                    marginBlockStart: 6,
                    fontSize: "var(--atlas-font-size-xs)",
                    fontWeight: 600,
                    lineHeight: 1.3,
                  }}
                >
                  {c.label}
                </div>
              </CardContent>
            </Card>
          </div>
        ))}
      </div>

      {/* Invite friends card */}
      <div style={{ padding: "0 var(--atlas-spacing-5)" }}>
        <Card variant="filled">
          <CardContent>
            <div style={{ display: "flex", gap: "var(--atlas-spacing-3)", alignItems: "center" }}>
              <span aria-hidden style={{ fontSize: 28 }}>🏠</span>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>
                  Earn up to ₪200 by inviting friends to Tabby
                </div>
                <a
                  href="#"
                  onClick={(e) => e.preventDefault()}
                  style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-primary)", fontWeight: 600 }}
                >
                  Learn more
                </a>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Stores for you */}
      <div
        style={{
          padding: "var(--atlas-spacing-5) var(--atlas-spacing-5) 0",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <strong style={{ fontSize: "var(--atlas-font-size-base)" }}>Stores For You</strong>
        <a
          href="#"
          onClick={(e) => e.preventDefault()}
          style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-primary)", fontWeight: 600 }}
        >
          View all
        </a>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: "var(--atlas-spacing-2)",
          padding: "var(--atlas-spacing-3) var(--atlas-spacing-5)",
        }}
      >
        {["Cole", "Glamzale", "Ecco", "Mumzw"].map((store) => (
          <div
            key={store}
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 4,
            }}
          >
            <div
              style={{
                width: 56,
                height: 56,
                borderRadius: "var(--atlas-radius-full)",
                background: "var(--atlas-background-muted)",
              }}
            />
            <span style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-muted)" }}>{store}</span>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }} />

      {/* Reset CTA so user can run the flow again */}
      <div style={{ padding: "var(--atlas-spacing-3) var(--atlas-spacing-5)" }}>
        <Badge size="sm" variant="success" dot>
          You&apos;re all set
        </Badge>
        <div style={{ marginBlockStart: "var(--atlas-spacing-2)" }}>
          <Button variant="outline" size="sm" onClick={() => goTo(0)}>
            Run the flow again
          </Button>
        </div>
      </div>

      {/* Bottom tab bar */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          padding: "var(--atlas-spacing-3) var(--atlas-spacing-4) var(--atlas-spacing-6)",
          borderTop: "1px solid var(--atlas-border)",
          background: "var(--atlas-background)",
        }}
      >
        {[
          { icon: "🔍", label: "Discover", active: true },
          { icon: "🛍️", label: "Shop" },
          { icon: "💳", label: "Money" },
          { icon: "👤", label: "Profile" },
        ].map((t) => (
          <div
            key={t.label}
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 2,
              color: t.active ? "var(--atlas-foreground)" : "var(--atlas-foreground-muted)",
            }}
          >
            <span aria-hidden style={{ fontSize: 18 }}>{t.icon}</span>
            <span style={{ fontSize: 10, fontWeight: 600 }}>{t.label}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

function QuickLink({ emoji, title, sub }: { emoji: string; title: string; sub: string }) {
  return (
    <Card variant="outlined" size="sm" interactive>
      <CardContent>
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-2)" }}>
          <span aria-hidden style={{ fontSize: 18 }}>{emoji}</span>
          <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>{title}</div>
        </div>
        <div style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-muted)", marginBlockStart: 2 }}>
          {sub}
        </div>
      </CardContent>
    </Card>
  )
}

"use client"

import React from "react"
import Link from "next/link"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { PhoneFrame } from "./PhoneFrame"
import { StepProgress } from "./StepProgress"

/**
 * FlowShell — outer page chrome for any prototype flow.
 *
 * Renders the page background, a small header with the flow title + a
 * "back to prototypes" link, an optional step progress bar, and the phone
 * frame that wraps the active screen.
 */
export function FlowShell({
  title,
  step,
  totalSteps,
  onReset,
  showProgress = true,
  phoneBackground,
  statusBarTint,
  homeIndicatorTint,
  children,
}: {
  title: string
  step: number
  totalSteps: number
  onReset?: () => void
  showProgress?: boolean
  phoneBackground?: string
  statusBarTint?: "dark" | "light"
  homeIndicatorTint?: "dark" | "light"
  children: React.ReactNode
}) {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--atlas-background-subtle)",
        color: "var(--atlas-foreground)",
        fontFamily: "var(--atlas-font-sans)",
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* Page header — outside the phone */}
      <header
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "var(--atlas-spacing-4) var(--atlas-spacing-6)",
          borderBottom: "1px solid var(--atlas-border)",
          background: "var(--atlas-background)",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
          <Link
            href="/prototypes"
            style={{
              fontSize: "var(--atlas-font-size-sm)",
              color: "var(--atlas-foreground-muted)",
              textDecoration: "none",
            }}
          >
            ← Prototypes
          </Link>
          <span style={{ color: "var(--atlas-border-strong)" }}>/</span>
          <strong style={{ fontSize: "var(--atlas-font-size-sm)" }}>{title}</strong>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
          <span
            style={{
              fontSize: "var(--atlas-font-size-xs)",
              color: "var(--atlas-foreground-muted)",
            }}
          >
            Step {step + 1} of {totalSteps}
          </span>
          {onReset && (
            <Button size="sm" variant="ghost" onClick={onReset}>
              Reset
            </Button>
          )}
        </div>
      </header>

      {/* Progress bar — full width, slim, under the header */}
      {showProgress && (
        <div style={{ padding: "var(--atlas-spacing-2) var(--atlas-spacing-6)" }}>
          <StepProgress total={totalSteps} current={step} />
        </div>
      )}

      {/* Phone frame */}
      <main
        style={{
          flex: 1,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "var(--atlas-spacing-8) var(--atlas-spacing-4)",
        }}
      >
        <PhoneFrame
          background={phoneBackground}
          statusBarTint={statusBarTint}
          homeIndicatorTint={homeIndicatorTint}
        >
          {children}
        </PhoneFrame>
      </main>
    </div>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"

/**
 * useFlowState — step state + form data for a multi-step prototype.
 *
 * - `step` is the active index (0-based).
 * - URL is kept in sync via `?step=N` so back/forward work and links share state.
 * - `data` is a typed bag of form values shared across steps.
 *
 * Refresh resets `data` (intentional — prototypes shouldn't persist).
 */
export function useFlowState<T extends Record<string, unknown>>(opts: {
  totalSteps: number
  initialData: T
  /** URL search param name. Default: "step". Pass null to disable URL sync. */
  param?: string | null
}) {
  const { totalSteps, initialData, param = "step" } = opts

  const [step, setStepState] = useState<number>(() => {
    if (typeof window === "undefined" || !param) return 0
    const url = new URL(window.location.href)
    const raw = url.searchParams.get(param)
    const parsed = raw ? parseInt(raw, 10) : 0
    if (Number.isNaN(parsed)) return 0
    return Math.max(0, Math.min(totalSteps - 1, parsed))
  })

  const [data, setData] = useState<T>(initialData)

  // Sync `step` → URL
  useEffect(() => {
    if (typeof window === "undefined" || !param) return
    const url = new URL(window.location.href)
    if (step === 0) {
      url.searchParams.delete(param)
    } else {
      url.searchParams.set(param, String(step))
    }
    window.history.replaceState(null, "", url.toString())
  }, [step, param])

  const goTo = useCallback(
    (next: number) => {
      setStepState(Math.max(0, Math.min(totalSteps - 1, next)))
    },
    [totalSteps],
  )

  const next = useCallback(() => goTo(step + 1), [goTo, step])
  const back = useCallback(() => goTo(step - 1), [goTo, step])
  const reset = useCallback(() => {
    setStepState(0)
    setData(initialData)
  }, [initialData])

  const patch = useCallback((partial: Partial<T>) => {
    setData((prev) => ({ ...prev, ...partial }))
  }, [])

  return {
    step,
    setStep: setStepState,
    goTo,
    next,
    back,
    reset,
    data,
    setData,
    patch,
    isFirst: step === 0,
    isLast: step === totalSteps - 1,
    totalSteps,
  }
}

