              selected={data.recipient?.id === r.id}
              onSelect={select}
            />
          ))}
          {results.length === 0 && (
            <div
              style={{
                fontSize: "var(--atlas-font-size-sm)",
                color: "var(--atlas-foreground-muted)",
                paddingBlock: "var(--atlas-spacing-4)",
                textAlign: "center",
              }}
            >
              No recipients match &ldquo;{data.search}&rdquo;.
            </div>
          )}
        </div>
      </div>

      <Button variant="outline" size="md" disabled>
        Add a new recipient
      </Button>
    </div>
  )
}

